(()=>{window.HD=(key,secs,tag)=>{const idx=D.findIndex(d=>d._key===key);PT8.launch({mode:'mp',rally:true,track:idx,laps:1,humans:[{id:'ford',alt:0}],ai:[]});const Rc=RACE;Rc.state='race';Rc.green=true;const c=Rc.cars.find(q=>q.human);const T=Rc.T;
const old=PT8.inPost;PT8.inPost=(cc,dt)=>{if(cc===c){const a=PT8._aiIn(cc,dt);cc.in.th=a.th;cc.in.br=a.br;cc.in.st=a.st}if(old)old(cc,dt)};
let air=0,n=0,maxYr=0,sl=[],maxSl=0,maxVy=0,spd=0,spin=0,dmg0=0;const log=[];
